    contentHtml: `<!-- target keyword: 자미두수 궁합 | secondary: 부처궁, 자미두수 연애운, 부처궁 해석 -->
<p><strong>자미두수 궁합</strong>의 출발점은 부처궁(夫妻宮)입니다. 부처궁은 내가 어떤 상대에게 끌리는지, 관계 안에서 어떤 역할을 맡는지, 어떤 패턴이 반복되는지를 보여주는 궁으로, 두 사람의 부처궁을 나란히 놓고 교차로 읽으면 '왜 이 관계가 이런 리듬으로 흘러가는지'가 구조적으로 보입니다. 점수 하나로 좋다·나쁘다를 가르는 궁합이 아니라, 관계의 사용 설명서를 읽는 방식에 가깝습니다.</p>
<h2>부처궁이 보여주는 세 가지</h2>
<p>부처궁은 상대방의 사주가 아니라 '나의 관계 방식'을 먼저 보여줍니다. 구체적으로는 첫째, 내가 무의식적으로 끌리는 상대의 유형. 둘째, 연애와 결혼에서 내가 취하는 역할과 거리 조절 방식. 셋째, 관계에서 반복되는 과제입니다. 그래서 상대가 바뀌어도 비슷한 연애 패턴이 반복된다면, 그 답은 상대가 아니라 내 부처궁에 있는 경우가 많습니다.</p>
<h2>부처궁 주성별 연애 패턴</h2>
<ul>
<li>자미·천부: 듬직하고 능력 있는 상대에게 끌리며, 관계에서도 격과 안정감을 중시</li>
<li>천동·태음: 다정하고 정서적인 교감이 최우선 — 보살핌을 주고받는 관계에 강함</li>
<li>탐랑·염정: 매력과 긴장감이 있는 연애 — 설렘이 크지만 권태에 취약</li>
<li>칠살·파군: 뜨겁게 시작하고 급격히 전환되는 드라마형 — 관계의 재구성이 잦음</li>
<li>거문: 대화가 핵심 — 말이 통하면 깊어지고, 말로 다투기 시작하면 소모전이 되기 쉬움</li>
<li>천량·천상: 연상·연하 등 보호자-피보호자 구도, 신뢰 기반의 안정형</li>
</ul>
<p>부처궁이 공궁이라면 대궁인 관록궁의 별을 빌려 읽습니다. 일하는 방식이 사랑하는 방식에 그대로 투영되는 유형입니다.</p>
<h2>갈등 신호: 화기와 살성 읽는 법</h2>
<p>부처궁에 화기(忌)가 들면 관계에 대한 집착·불안·소유욕이 과제로 나타납니다. 이것은 '결혼이 나쁘다'는 판결이 아니라, 관계에서 결핍감을 느끼는 지점이 명확하다는 뜻이므로 그 지점을 언어화하는 것이 최선의 대응입니다. 경양·타라·화성·영성 같은 살성이 동궁하면 다툼의 방식(직설·냉전·폭발·잔불)이 드러나고, 좌보·우필이 부처궁에 들면 관계에 제3자의 개입 변수가 생기기 쉽다고 봅니다. 사화의 원리는 <a href="/insights/ziwei-sihua/">사화 해석 가이드</a>에서 확인하세요.</p>
<h2>두 사람의 명반을 교차로 읽는 순서</h2>
<p>실전 궁합은 다음 순서로 봅니다.</p>
<ul>
<li>각자의 부처궁 주성·밝기 확인 — 서로의 관계 방식 파악</li>
<li>내 부처궁의 별과 상대 명궁의 별이 닮았는지 확인 — 닮을수록 '내가 그리던 유형'</li>
<li>서로의 생년 사화가 상대의 명궁·부처궁에 어떤 화를 던지는지 확인 — 화록을 주면 호감과 지원, 화기를 주면 신경 쓰이고 얽히는 인연</li>
<li>부처궁의 삼방사정(천이궁·복덕궁·관록궁) 확인 — 관계가 생활·일과 맞물리는 방식</li>
</ul>
<h2>시기까지 보려면: 대한과 유년의 부처궁</h2>
<p>결혼·재회·이별 같은 사건의 시기는 타고난 부처궁이 아니라 현재 대한의 부처궁과 그 해 유년(流年) 부처궁으로 봅니다. 대한 부처궁에 화록·천희·홍란 같은 인연의 별이 모이는 시기에 만남과 결혼 이슈가 활성화되고, 화기가 충격을 주는 시기에는 관계 재정비 이슈가 올라옵니다.</p>
<p>내 부처궁의 별이 궁금하다면 <a href="/ziwei/">자미두수 무료 명반</a>에서 확인하고, 관계 고민을 구체적으로 풀고 싶다면 <a href="/ziwei-ai/">자미두수 전문가 상담</a>에 이어서 질문해보세요. 오행 기반의 다른 관점이 필요하면 <a href="/compatibility/">사주 궁합</a>과 교차 확인하는 것도 좋은 방법입니다 — 두 도구의 차이는 <a href="/insights/ziwei-vs-saju/">자미두수와 사주의 차이</a>에서 다룹니다.</p>`,
