    description: "영친관계는 숙요점 6유형 궁합 가운데 가장 안정적이고 이상적인 인연으로 꼽힙니다. 영(榮)과 친(親)의 의미, 연애·결혼·친구·직장·사업별 특징과 오래 유지하는 법을 정리했습니다.",
