    contentHtml: `<!-- target keyword: 대운 세운 차이 | secondary: 대운 보는 법, 세운, 대운수 -->
<p><strong>대운과 세운의 차이</strong>는 시간 단위입니다. 대운(大運)은 10년마다 바뀌는 간지의 흐름으로 인생의 계절을, 세운(歲運)은 그 해의 간지(예: 2026년 병오년)로 그해의 날씨를 보여줍니다. 타고난 사주가 지형이라면 대운은 계절, 세운은 날씨 — 이 세 겹을 함께 읽는 것이 시기 해석의 기본 구조입니다.</p>
<h2>대운: 월주에서 출발하는 10년 단위의 간지</h2>
<p>대운은 태어난 달의 간지(월주)를 기준으로, 연간의 음양과 성별에 따라 순행 또는 역행하며 60갑자 순서대로 배치됩니다. 몇 살부터 대운이 시작되는지가 사람마다 다른데 이를 대운수라 하며, 만세력에서 자동으로 계산해줍니다. 예컨대 대운수가 4라면 4세, 14세, 24세… 마다 대운 간지가 바뀝니다. 대운은 그 10년 동안 내 사주에 새로 들어와 함께 작동하는 두 글자이므로, 같은 사주라도 대운에 따라 발현되는 십성과 오행이 달라집니다.</p>
<h2>세운: 매년 입춘에 바뀌는 그 해의 간지</h2>
<p>세운은 해마다 돌아오는 그 해의 간지입니다. 경계는 1월 1일이 아니라 입춘(양력 2월 4일경)이라는 점을 기억하세요. 세운의 천간과 지지가 내 일간과 어떤 십성 관계를 맺는지, 원국의 글자들과 합·충을 일으키는지에 따라 그해의 테마가 정해집니다. 신년운세가 계산되는 원리가 바로 이 세운 분석입니다.</p>
<h2>함께 읽는 법: 대운은 무대, 세운은 사건</h2>
<p>실전에서는 두 흐름의 조합으로 판단합니다.</p>
<ul>
<li>대운 좋음 + 세운 좋음: 확장의 적기, 큰 결정과 투자를 앞당길 만한 구간</li>
<li>대운 좋음 + 세운 나쁨: 방향은 유지하되 그해의 속도만 조절</li>
<li>대운 나쁨 + 세운 좋음: 단기 기회는 취하되 구조적인 확장은 신중하게</li>
<li>대운 나쁨 + 세운 나쁨: 수성과 정비의 해, 체력·재무의 기초 다지기</li>
</ul>
<p>대운이 바뀌는 교운기(대운 전환 전후 1~2년)는 환경과 관심사가 크게 재편되는 시기이므로, 이 무렵의 이직·이사·관계 변화는 자연스러운 현상으로 받아들이되 계약과 문서는 더 꼼꼼히 챙기는 것이 좋습니다.</p>
<h2>계획에 연결하기</h2>
<p>연초에 내 현재 대운의 키워드를 한 줄로 정리하고, 올해 세운이 그 키워드를 돕는지 방해하는지 판단해 연간 목표의 공격/수비 비중을 정하세요. 같은 '10년+1년' 이중 구조를 자미두수에서는 대한과 유년으로 읽는데, 도구를 비교하며 익히고 싶다면 <a href="/insights/ziwei-decade-and-annual-flow-reading-guide/">자미두수 대한·유년 해석 가이드</a>가 좋은 참고가 됩니다.</p>
<p>내 대운수와 현재 대운 간지는 <a href="/saju/">무료 사주풀이</a>에서 바로 확인할 수 있습니다. 올해 세운을 계획으로 바꾸는 구체적인 방법은 <a href="/insights/new-year-fortune-framework/">신년운세 활용 프레임</a>에서, 대화형으로 짚고 싶다면 <a href="/new-year-ai-consultation/">신년 전문가 상담</a>에서 이어가 보세요.</p>`,
