    description: "속마음 리딩은 가장 인기 있으면서 가장 과잉 해석의 위험이 큰 주제입니다. 카드는 진실이 아니라 감지된 에너지라는 원칙, 안전한 3카드 스프레드, 조심스러운 표현법까지 정리했습니다.",
    category: "타로",
    keywords: ["상대방 속마음 타로", "속마음 타로", "그 사람 마음 타로", "연애 타로", "짝사랑 타로"],
